-- ==============================================================
-- ADEGA DO VADO & HENRI IMPORTS TABACARIA
-- Migração Completa e Sanitizada para Banco de Dados Neon
-- Gerado automaticamente a partir do backup auditado
-- 100% Livre de Base64 | Idempotente com ON CONFLICT
-- ==============================================================

BEGIN;

-- 1. TIPOS ENUM
DO $$ BEGIN
  CREATE TYPE public.order_source AS ENUM ('ONLINE', 'INTERNO', 'WHATSAPP');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
  CREATE TYPE public.order_status AS ENUM (
    'NOVO', 'RECEBIDO', 'EM_PREPARACAO', 'EM_SEPARACAO', 'SEPARADO',
    'PRONTO', 'AGUARDANDO_RETIRADA', 'EM_ENTREGA', 'CONCLUIDO', 'CANCELADO', 'AGUARDANDO_PAGAMENTO'
  );
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
  CREATE TYPE public.order_type AS ENUM ('DELIVERY', 'RETIRADA', 'BALCAO');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
  CREATE TYPE public.profile_role AS ENUM (
    'ADMIN', 'GERENTE', 'ATENDENTE', 'RECEBIMENTO', 'PREPARACAO', 'SEPARACAO', 'ENTREGA'
  );
EXCEPTION WHEN duplicate_object THEN null; END $$;

-- 2. TABELAS BASE
CREATE TABLE IF NOT EXISTS public.categories (
    id text NOT NULL PRIMARY KEY,
    store_id text NOT NULL,
    name text NOT NULL,
    image text,
    subcategories text[] DEFAULT '{Todos}'::text[],
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.settings (
    store_id text NOT NULL PRIMARY KEY,
    name text NOT NULL,
    whatsapp text,
    niche text,
    instagram text,
    tiktok text,
    slogan text,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    "storeCep" text,
    "deliveryFeePerKm" numeric,
    "deliveryBaseFee" numeric,
    "deliveryInfo" text
);

CREATE TABLE IF NOT EXISTS public.customers (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    store_id text NOT NULL,
    name text NOT NULL,
    phone text,
    cep text,
    street text,
    number text,
    complement text,
    neighborhood text,
    city text,
    state text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid UNIQUE,
    store_id text NOT NULL,
    role public.profile_role DEFAULT 'ATENDENTE'::public.profile_role NOT NULL,
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.products (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    store_id text NOT NULL,
    name text NOT NULL,
    description text,
    price numeric NOT NULL,
    image text,
    category text REFERENCES public.categories(id) ON DELETE SET NULL,
    subcategory text,
    is_customizable boolean DEFAULT false,
    is_active boolean DEFAULT true,
    available_colors text[],
    has_name_option boolean DEFAULT false,
    name_price numeric DEFAULT 0,
    variations jsonb DEFAULT '[]'::jsonb,
    customization_lists jsonb DEFAULT '[]'::jsonb,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    wholesale_price numeric,
    wholesale_min_quantity integer DEFAULT 10,
    stock_quantity integer DEFAULT 0,
    promotional_price numeric(10,2),
    images text[] DEFAULT '{}'::text[]
);

CREATE TABLE IF NOT EXISTS public.orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    store_id text NOT NULL,
    order_number integer NOT NULL,
    source public.order_source NOT NULL,
    order_type public.order_type NOT NULL,
    status public.order_status DEFAULT 'NOVO'::public.order_status NOT NULL,
    customer_id uuid REFERENCES public.customers(id),
    customer_name text,
    customer_phone text,
    delivery_cep text,
    delivery_street text,
    delivery_number text,
    delivery_complement text,
    delivery_neighborhood text,
    delivery_city text,
    delivery_state text,
    payment_method text,
    payment_status text DEFAULT 'PENDENTE'::text,
    amount_received numeric(10,2),
    change_for numeric(10,2),
    subtotal numeric(10,2) DEFAULT 0 NOT NULL,
    delivery_fee numeric(10,2) DEFAULT 0 NOT NULL,
    discount numeric(10,2) DEFAULT 0 NOT NULL,
    total numeric(10,2) DEFAULT 0 NOT NULL,
    notes text,
    created_by uuid REFERENCES public.profiles(id),
    received_by uuid REFERENCES public.profiles(id),
    preparing_by uuid REFERENCES public.profiles(id),
    separating_by uuid REFERENCES public.profiles(id),
    delivery_by uuid REFERENCES public.profiles(id),
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    received_at timestamp with time zone,
    preparing_at timestamp with time zone,
    separating_at timestamp with time zone,
    ready_at timestamp with time zone,
    delivery_started_at timestamp with time zone,
    delivered_at timestamp with time zone,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancelled_by uuid REFERENCES public.profiles(id),
    cancel_reason text
);

CREATE TABLE IF NOT EXISTS public.order_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    order_id uuid REFERENCES public.orders(id) ON DELETE CASCADE,
    product_id text,
    product_name text NOT NULL,
    quantity integer NOT NULL,
    unit_price numeric(10,2) NOT NULL,
    total_price numeric(10,2) NOT NULL,
    options jsonb,
    notes text,
    status text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.order_status_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    order_id uuid REFERENCES public.orders(id) ON DELETE CASCADE,
    store_id text NOT NULL,
    from_status public.order_status,
    to_status public.order_status NOT NULL,
    changed_by uuid REFERENCES public.profiles(id),
    changed_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    notes text
);

CREATE TABLE IF NOT EXISTS public.global_options (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    type text,
    name text,
    price numeric,
    image text,
    category_ids text[],
    "group" text
);

-- 3. ÍNDICES DE PERFORMANCE
CREATE INDEX IF NOT EXISTS idx_products_store_id ON public.products(store_id);
CREATE INDEX IF NOT EXISTS idx_products_category ON public.products(category);
CREATE INDEX IF NOT EXISTS idx_orders_store_id ON public.orders(store_id);
CREATE INDEX IF NOT EXISTS idx_orders_status ON public.orders(status);
CREATE INDEX IF NOT EXISTS idx_orders_created_at ON public.orders(created_at);
CREATE INDEX IF NOT EXISTS idx_order_items_order_id ON public.order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_order_status_history_order_id ON public.order_status_history(order_id);

